cd /workspace/ROAM-Artifact/Evaluation && python - << 'PY'
from pathlib import Path
lines = Path('results.md').read_text().splitlines()
rows = []
for line in lines[4:]:
    if not line.startswith('|'):
        continue
    parts = [p.strip() for p in line.split('|')]
    if len(parts) < 58:
        continue
    # parts[1] is row index, ensure it's digit
    if not parts[1].isdigit():
        continue
    rows.append(parts)

print('num rows:', len(rows))

idx_missing = 6
idx_roam = 8
idx_recdroid = 23
idx_yakusu = 55

all_total = len(rows)

stats = {
    'ROAM': {'all':0, 'miss':0, 'nomiss':0},
    'ReCDroid': {'all':0, 'miss':0, 'nomiss':0},
    'Yakusu': {'all':0, 'miss':0, 'nomiss':0},
}

miss_total = 0
nomiss_total = 0

for r in rows:
    try:
        missing = float(r[idx_missing])
    except ValueError:
        missing = 0.0
    has_missing = missing > 0
    if has_missing:
        miss_total += 1
    else:
        nomiss_total += 1
    for name, idx in [('ROAM', idx_roam), ('ReCDroid', idx_recdroid), ('Yakusu', idx_yakusu)]:
        val = r[idx].lower() if r[idx] else ''
        if val == 'success':
            stats[name]['all'] += 1
            if has_missing:
                stats[name]['miss'] += 1
            else:
                stats[name]['nomiss'] += 1

print('miss_total, nomiss_total:', miss_total, nomiss_total)
for name in ['ReCDroid','Yakusu','ROAM']:
    s = stats[name]
    print(name, 'success counts:', s)
    print('  all % =', 100*s['all']/all_total)
    print('  nomiss % =', 100*s['nomiss']/nomiss_total)
    print('  miss % =', 100*s['miss']/miss_total)
